import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {auditCallback} from '../src/routes/orders.ts';
import {unrelatedHelper, documentation} from '../src/routes/accounts.ts';

function createMockRes() {
  return {
    sent: null,
    send(value) {
      this.sent = value;
      return value;
    }
  };
}

describe('Router registration order and routes', () => {
  it('preserves route registration order and methods', () => {
    const router = makeRouter();
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({method: r.method, path: r.path})),
      [
        {method: 'GET', path: '/accounts/:id'},
        {method: 'POST', path: '/accounts'},
        {method: 'GET', path: '/health'},
        {method: 'GET', path: '/orders/:id'},
        {method: 'DELETE', path: '/orders/:id'}
      ]
    );
  });
});

describe('Successful request handling', () => {
  it('GET /accounts/:id handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    const req = {id: 'acc-1'};
    const res = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler(req, res, next);
    assert.equal(result, 'account:acc-1');
    assert.equal(res.sent, 'account:acc-1');
    assert.equal(nextCalled, false);
  });

  it('POST /accounts handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    const req = {id: 'acc-2'};
    const res = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler(req, res, next);
    assert.equal(result, 'created:acc-2');
    assert.equal(res.sent, 'created:acc-2');
    assert.equal(nextCalled, false);
  });

  it('GET /health preserves synchronous handling', () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/health');
    const req = {id: 'h1'};
    const res = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = route.handler(req, res, next);
    assert.equal(result, 'ok');
    assert.equal(res.sent, 'ok');
    assert.equal(nextCalled, false);
    // Verify it is not a Promise
    assert.equal(result instanceof Promise, false);
  });

  it('GET /orders/:id handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    const req = {id: 'ord-1'};
    const res = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler(req, res, next);
    assert.equal(result, 'ORD-1');
    assert.equal(res.sent, 'ORD-1');
    assert.equal(nextCalled, false);
  });

  it('DELETE /orders/:id handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    const req = {id: 'ord-2'};
    const res = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler(req, res, next);
    assert.equal(result, 'deleted:ord-2');
    assert.equal(res.sent, 'deleted:ord-2');
    assert.equal(nextCalled, false);
  });
});

describe('Error forwarding to next', () => {
  it('GET /accounts/:id forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    const req = {id: 'acc-1', fail: true};
    const res = createMockRes();
    const errors = [];
    const next = (err) => { errors.push(err); };

    await route.handler(req, res, next);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'account read');
  });

  it('POST /accounts forwards error to next when named async handler throws', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    const req = {id: 'acc-2', fail: true};
    const res = createMockRes();
    const errors = [];
    const next = (err) => { errors.push(err); };

    await route.handler(req, res, next);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'account create');
  });

  it('GET /orders/:id forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    const req = {id: 'ord-1', fail: true};
    const res = createMockRes();
    const errors = [];
    const next = (err) => { errors.push(err); };

    await route.handler(req, res, next);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'order read');
  });

  it('DELETE /orders/:id forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    const req = {id: 'ord-2', fail: true};
    const res = createMockRes();
    const errors = [];
    const next = (err) => { errors.push(err); };

    await route.handler(req, res, next);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'order delete');
  });
});

describe('Unrelated helpers and callbacks are preserved', () => {
  it('documentation constant is preserved', () => {
    assert.equal(documentation, "router.get('/fake', async handler)");
  });

  it('unrelatedHelper is not wrapped and throws directly', async () => {
    await assert.rejects(async () => {
      await unrelatedHelper();
    }, {name: 'Error', message: 'helper'});
  });

  it('auditCallback is not wrapped and throws directly', async () => {
    await assert.rejects(async () => {
      await auditCallback();
    }, {name: 'Error', message: 'audit'});
  });
});

